import { Link, Outlet, useLocation } from 'react-router-dom';
import { useState } from 'react';

const AdminLayout = () => {
    const user = JSON.parse(localStorage.getItem('user')) || {};
    const location = useLocation();
    const [collapsed, setCollapsed] = useState(false);

    const handleLogout = () => {
        localStorage.clear();
        window.location.href = '/';
    };

    const MenuItem = ({ to, icon, label }) => {
        const active = location.pathname.includes(to);
        return (
            <Link to={to} style={{
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                padding: '10px 15px',
                borderRadius: 8,
                marginBottom: 6,
                textDecoration: 'none',
                fontWeight: 500,
                color: active ? '#fff' : '#333',
                background: active ? '#4a90e2' : 'transparent'
            }}>
                <span style={{ fontSize: 18 }}>{icon}</span>
                {!collapsed && <span>{label}</span>}
            </Link>
        );
    };

    return (
        <div style={{ display: 'flex', height: '100vh' }}>
            {/* Sidebar */}
            <aside style={{
                width: collapsed ? 70 : 220,
                background: '#f8f9fc',
                padding: '15px 10px',
                borderRight: '1px solid #ccc',
                transition: '0.3s'
            }}>
                <div style={{ textAlign: 'center', marginBottom: 20 }}>
                    <img
                        src="https://res.cloudinary.com/dfyk60djc/image/upload/v1746078924/professional-home-build-logo_111366-35_rdzlit.jpg"
                        alt="logo"
                        width="40"
                        style={{ borderRadius: '8px' }}
                    />
                    {!collapsed && <h3 style={{ margin: 0, fontSize: 16 }}>Xây Dựng</h3>}
                </div>

                <MenuItem to="/admin/dashboard" icon="📊" label="Dashboard" />
                <MenuItem to="/admin/projects" icon="📁" label="Dự án" />
                <MenuItem to="/admin/employees" icon="👥" label="Nhân sự" />
                <MenuItem to="/admin/materials" icon="📦" label="Vật tư" />

                <button onClick={handleLogout} style={{
                    marginTop: 30,
                    width: '100%',
                    padding: '10px',
                    background: '#007bff',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 8,
                    fontWeight: 'bold',
                    cursor: 'pointer'
                }}>🔓 Đăng xuất</button>
            </aside>


            {/* Main */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                {/* Header */}
                <header style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '10px 20px',
                    borderBottom: '1px solid #ddd',
                    background: '#fff',
                    boxShadow: '0 2px 6px rgba(0,0,0,0.05)'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                        <button onClick={() => setCollapsed(!collapsed)} style={circleBtn}>☰</button>
                        <h2 style={{ margin: 0 }}>Xây Dựng Bình Định</h2>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 15 }}>
                        <button style={circleBtn}>🌙</button>
                        <button style={circleBtn}>🔔</button>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                            <div style={{
                                background: '#2962ff', color: '#fff', width: 32, height: 32,
                                borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center'
                            }}>{user.name?.charAt(0) || 'A'}</div>
                            <div>
                                <strong>{user.name || 'Admin'}</strong><br />
                                <span style={{ fontSize: 12, color: '#666' }}>{user.email}</span>
                            </div>
                        </div>
                    </div>
                </header>

                {/* Content */}
                <main style={{ padding: 20, flex: 1, overflowY: 'auto' }}>
                    <Outlet />
                </main>
            </div>
        </div>
    );
};

const circleBtn = {
    border: 'none',
    background: '#eef2ff',
    borderRadius: '50%',
    width: 32,
    height: 32,
    fontSize: 16,
    cursor: 'pointer'
};

export default AdminLayout;
